def main():
    p=argparse.ArgumentParser(description=__doc__); p.add_argument('--write', action='store_true'); a=p.parse_args()
    path=pathlib.Path('work/glossary/continuation_terms.en.json'); data=json.loads(path.read_text(encoding='utf8'))
    existing={e['id']:e for e in data['entries']}; added=[]
    for entry in ENTRIES:
        if entry['id'] in existing:
            if existing[entry['id']] != entry: raise ValueError('Existing entry differs; explicit review required')
        else: added.append(entry)
    profile_path=pathlib.Path('work/glossary/heroes_phantasia.en.json')
    profiles=json.loads(profile_path.read_text(encoding='utf8'))
    profile=next(e for e in profiles['entries'] if e['id']=='character_084')
    if profile['en']!='Shizuru Fujino':raise ValueError('Profile identity changed')
    update=dict(nickname='Shizuru', gender='female', personality='Calm; unhurried manner and Kyoto accent', role='Fuka Academy student council president',
        confidence=dict(appearance='high',name='high',gender='high',personality='researched',role='researched'),
        notes='Official profile confirms name reading, female identity and Kyoto dialect; wiki anime list confirms English spelling and council role. Do not import Shizuru Viola from My-Otome.')
    update['sources']=list(dict.fromkeys(profile['sources']+['https://mai.fandom.com/wiki/Mai-HiME_characters_(anime)','https://www.sunrise-inc.co.jp/my-hime/web/character/chara/shizuru.html']))
    changed=any(profile.get(k)!=v for k,v in update.items())
    if changed and profile['gender'] not in ('unknown','female'):raise ValueError('Profile gender conflict requires review')
    print(json.dumps({'added':len(added),'sample':added,'profile_updates':[dict(id=profile['id'],**update)] if changed else []},ensure_ascii=True,indent=2))
    if a.write:
        data['entries'].extend(added);path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
        if changed:
            profile.update(update);profile_path.write_text(json.dumps(profiles,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
    else: print('DRY RUN: glossary unchanged.')

if __name__=='__main__':main()
